function publicDisplayText(value, fallback='') {
 if (typeof value === 'string' || typeof value === 'number') return String(value);
 return fallback;
}
function publicContentText(data, keys) {
 if (!data || typeof data !== 'object') return '';
 for (const key of keys) {
  const value = data[key];
  if (typeof value === 'string' && value.trim()) return value.trim();
 }
 return '';
}
function formatPublicDate(value) {
 const date = value ? new Date(value) : null;
 if (!date || Number.isNaN(date.getTime())) return 'Schedule to be confirmed';
 return new Intl.DateTimeFormat('en-KE',{day:'numeric',month:'short',year:'numeric'}).format(date);
}

const financePageKeys=new Set(['finance','payments','accounts','journals','budgets','reconciliation','suppliers']);
const seniorRoles=['super_admin','international_executive','national_admin','regional_overseer','district_pastor','branch_pastor'];
const sensitiveRoles=['super_admin','international_executive','national_admin','branch_pastor'];
const branchAdminRoles=[...seniorRoles,'branch_admin'];
function visibleForRole(key,role){
 if(['branding','websiteContent'].includes(key))return ['super_admin','international_executive','national_admin'].includes(role);
 if(role==='member')return key==='memberPortal'||key==='security';
 if(key==='gallery')return branchAdminRoles.includes(role);
 if(key==='pastoral')return ['super_admin','international_executive','national_admin','branch_pastor'].includes(role);
 if(key==='registrations')return ['super_admin','international_executive','national_admin','branch_admin','branch_pastor'].includes(role);
 if(role==='treasurer')return ['dashboard','security','finance','payments','accounts','journals','budgets','reconciliation','suppliers','reports'].includes(key);
 if(role==='department_leader')return ['dashboard','security','attendance','departments','events','discipleship','services'].includes(key);
 if(key==='memberPortal')return false;
 if(key==='reports')return branchAdminRoles.includes(role);
 if(key==='audit')return seniorRoles.includes(role);
 if(financePageKeys.has(key))return seniorRoles.includes(role)||role==='treasurer';
 if(['safeguarding','discipline','counselling','benevolence','welfare','prayer'].includes(key))return sensitiveRoles.includes(role);
 return branchAdminRoles.includes(role);
}
