function scrollPageToTop() {
 const reset = () => {
  window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  document.documentElement.scrollTop = 0;
  document.body.scrollTop = 0;
  document.querySelectorAll('.main, .content, main, [data-page-scroll]').forEach(element => {
   element.scrollTop = 0;
   element.scrollLeft = 0;
  });
 };
 reset();
 if (typeof window.requestAnimationFrame === 'function') window.requestAnimationFrame(reset);
}
function organisationHierarchyRows(records) {
 const byId=new Map((records||[]).map(org=>[String(org._id),{...org,children:[]}]));
 const roots=[];
 for(const org of records||[]){const node=byId.get(String(org._id));const parentId=org.parent?String(org.parent?._id??org.parent):'';const parent=parentId?byId.get(parentId):null;if(parent&&parent!==node)parent.children.push(node);else roots.push(node);}
 const levelOrder={international:0,national:1,regional:2,district:3,branch:4};
 const sort=items=>items.sort((x,y)=>(levelOrder[x.level]??9)-(levelOrder[y.level]??9)||String(x.name).localeCompare(String(y.name)));
 const rows=[],visited=new Set();
 const walk=(items,depth)=>{for(const node of sort(items)){const id=String(node._id);if(visited.has(id))continue;visited.add(id);rows.push({...node,depth});walk(node.children,depth+1);}};
 walk(roots,0);for(const node of byId.values())if(!visited.has(String(node._id)))rows.push({...node,depth:0});return rows;
}
function eventDateParts(value) {
 const date=value?new Date(value):null;
 if(!date||Number.isNaN(date.getTime()))return {day:'—',month:'TBA'};
 return {day:new Intl.DateTimeFormat('en-KE',{day:'2-digit'}).format(date),month:new Intl.DateTimeFormat('en-KE',{month:'short'}).format(date).toUpperCase()};
}

