     <div className="dashboard-section-heading"><div><span className="eyebrow">KEY INDICATORS</span><h2>{role==='treasurer'?'Confirmed financial activity':role==='department_leader'?'Attendance activity':'Church at a glance'}</h2><p>Current month · based on records available within your assigned access</p></div></div>
     {dashboardStats.length?<div className="stats-grid dashboard-stats">{dashboardStats.map(([key,label,Icon,hint])=>{const raw=dashboardMetrics[key];const value=key==='confirmedIncomeThisMonth'||key==='confirmedExpensesThisMonth'?money(raw):raw;return <article className="stat-card dashboard-stat-card" key={key}><div className="stat-top"><span>{label}</span><div className="stat-icon"><Icon size={20}/></div></div><strong className={typeof value==='string'?'money-value':''}>{value}</strong><small>{hint}</small></article>;})}</div>:<div className="panel dashboard-empty"><div className="empty-state">No dashboard indicators are available for this account yet. Your account may have a restricted role or no records in its reporting scope.</div></div>}{Object.values(dashboard?.approvalBreakdown||{}).some(value=>Number(value)>0)&&<section className="panel dashboard-approvals"><div className="panel-heading"><div><span className="eyebrow">ACTION REQUIRED</span><h3>Approval queues</h3><p>Items awaiting review within your authorised scope</p></div><span className="count-badge">{dashboardMetrics.pendingApprovals||0} pending</span></div><div className="dashboard-approval-grid">{Object.entries(dashboard.approvalBreakdown||{}).filter(([,value])=>Number(value)>0).map(([key,value])=>{const targets={registrations:['registrations','Registration requests'],organisations:['organisations','Organisation requests'],finance:['finance','Financial decisions'],budgets:['budgets','Budget proposals'],operations:[null,'Operational records']};const target=targets[key];return <div className="dashboard-approval-item" key={key}><span><b>{value}</b><small>{target?.[1]||key}</small></span>{target?.[0]&&visibleForRole(target[0],role)&&<button type="button" onClick={()=>navigateTo(target[0])}>Review <ArrowUpRight size={13}/></button>}</div>;})}</div></section>}
